    wire [NUM_SLAVE-1:0] ar_select [NUM_MASTER-1:0];
    wire [NUM_MASTER-1:0] aw_grant [NUM_SLAVE-1:0];
    wire [NUM_MASTER-1:0] ar_grant [NUM_SLAVE-1:0];
    
    // Address decoder for each master
    generate
        for (g_m = 0; g_m < NUM_MASTER; g_m = g_m + 1) begin : master_decode
            // Simple decode based on upper address bits
            assign aw_select[g_m] = (g_m < NUM_MASTER && M0_AWADDR[31:28] < NUM_SLAVE) ? 
                                   (1 << M0_AWADDR[31:28]) : {NUM_SLAVE{1'b0}};
            assign ar_select[g_m] = (g_m < NUM_MASTER && M0_ARADDR[31:28] < NUM_SLAVE) ? 
                                   (1 << M0_ARADDR[31:28]) : {NUM_SLAVE{1'b0}};
