    //-------------------------------------------------------------------
    // Firewall Error Response Generation
    //-------------------------------------------------------------------
    
    // Master 0 error response generation
    reg m0_bvalid_err, m0_rvalid_err;
    reg m0_rlast_err;
    reg [WIDTH_ID-1:0] m0_bid_err, m0_rid_err;
    
    always @(posedge ACLK or negedge ARESETn) begin
        if (!ARESETn) begin
            m0_bvalid_err <= 1'b0;
            m0_rvalid_err <= 1'b0;
            m0_rlast_err <= 1'b0;
            m0_bid_err <= {WIDTH_ID{1'b0}};
            m0_rid_err <= {WIDTH_ID{1'b0}};
        end else begin
            // Generate DECERR response for blocked write transactions
            if (aw_firewall_block[0]) begin
                m0_bvalid_err <= 1'b1;
                m0_bid_err <= M0_AWID;
            end else if (m0_bvalid_err && M0_BREADY) begin
                m0_bvalid_err <= 1'b0;
            end
            
            // Generate DECERR response for blocked read transactions
            if (ar_firewall_block[0]) begin
                m0_rvalid_err <= 1'b1;
                m0_rlast_err <= 1'b1;
                m0_rid_err <= M0_ARID;
            end else if (m0_rvalid_err && M0_RREADY) begin
                m0_rvalid_err <= 1'b0;
                m0_rlast_err <= 1'b0;
            end
        end
    end
    
    // Master response assignments are handled by the crossbar
    // Blocked transactions are prevented at the VALID level
    
    // Master 1 error response generation
    reg m1_bvalid_err, m1_rvalid_err;
    reg m1_rlast_err;
    reg [WIDTH_ID-1:0] m1_bid_err, m1_rid_err;
    
    always @(posedge ACLK or negedge ARESETn) begin
        if (!ARESETn) begin
            m1_bvalid_err <= 1'b0;
            m1_rvalid_err <= 1'b0;
