            master_pending_addr[27] <= 32'h0;
            master_coherent_transaction[27] <= 1'b0;
        end else begin
            case (master_coherency_state[27])
                COHERENT_IDLE: begin
                    if (m27_awvalid && (m27_awdomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[27] <= COHERENT_WRITE_PENDING;
