    `ifdef ENABLE_ASSERTIONS
    // ACE-Lite protocol assertions
    property ace_lite_awsnoop_valid;
        @(posedge clk) disable iff (!rst_n)
        $onehot0({awsnoop == 3'b000, awsnoop == 3'b001, awsnoop == 3'b010, awsnoop == 3'b100});
    endproperty
    assert property (ace_lite_awsnoop_valid) else $error("[ASSERTION] Invalid AWSNOOP value");

    // Coherency state consistency
    property coherent_transaction_domain;
        @(posedge clk) disable iff (!rst_n)
        (awvalid && awdomain != 2'b00) |-> (awsnoop != 3'b000);
    endproperty
    assert property (coherent_transaction_domain) else $error("[ASSERTION] Non-shareable domain with coherent snoop");

    `endif // ENABLE_ASSERTIONS

