        resolved_awdomain[30] = resolve_domain(m30_awaddr, m30_awdomain);
        
        // Read address domain resolution
        resolved_ardomain[30] = resolve_domain(m30_araddr, m30_ardomain);
    end

    // Master 30 domain violation detection
    always @(*) begin
        domain_violation[30] = 1'b0;
        
        // Check write transaction violations
        if (m30_awvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(30, m30_awdomain)) begin
                domain_violation[30] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m30_awdomain != DOMAIN_NON_SHAREABLE) && 
                (m30_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
                domain_violation[30] = 1'b1;
            end
        end
        
        // Check read transaction violations
        if (m30_arvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(30, m30_ardomain)) begin
                domain_violation[30] = 1'b1;
            end
            // Check snoop consistency with domain
