    // Master 26 cache state interface
    , input  wire [WIDTH_AD-1:0]    m26_addr          // Address for state lookup
    , input  wire                   m26_state_req     // State query request
    , input  wire [2:0]             m26_new_state     // New cache state to set
    , input  wire                   m26_state_update  // Update cache state
    , output reg  [2:0]             m26_current_state // Current cache state
    , output reg                    m26_state_valid   // State lookup valid
    // Master 27 cache state interface
    , input  wire [WIDTH_AD-1:0]    m27_addr          // Address for state lookup
    , input  wire                   m27_state_req     // State query request
    , input  wire [2:0]             m27_new_state     // New cache state to set
    , input  wire                   m27_state_update  // Update cache state
    , output reg  [2:0]             m27_current_state // Current cache state
    , output reg                    m27_state_valid   // State lookup valid
    // Master 28 cache state interface
    , input  wire [WIDTH_AD-1:0]    m28_addr          // Address for state lookup
    , input  wire                   m28_state_req     // State query request
    , input  wire [2:0]             m28_new_state     // New cache state to set
    , input  wire                   m28_state_update  // Update cache state
    , output reg  [2:0]             m28_current_state // Current cache state
    , output reg                    m28_state_valid   // State lookup valid
    // Master 29 cache state interface
    , input  wire [WIDTH_AD-1:0]    m29_addr          // Address for state lookup
    , input  wire                   m29_state_req     // State query request
    , input  wire [2:0]             m29_new_state     // New cache state to set
    , input  wire                   m29_state_update  // Update cache state
    , output reg  [2:0]             m29_current_state // Current cache state
    , output reg                    m29_state_valid   // State lookup valid
    // Master 30 cache state interface
    , input  wire [WIDTH_AD-1:0]    m30_addr          // Address for state lookup
    , input  wire                   m30_state_req     // State query request
    , input  wire [2:0]             m30_new_state     // New cache state to set
    , input  wire                   m30_state_update  // Update cache state
    , output reg  [2:0]             m30_current_state // Current cache state
    , output reg                    m30_state_valid   // State lookup valid
    // Master 31 cache state interface
    , input  wire [WIDTH_AD-1:0]    m31_addr          // Address for state lookup
    , input  wire                   m31_state_req     // State query request
    , input  wire [2:0]             m31_new_state     // New cache state to set
    , input  wire                   m31_state_update  // Update cache state
    , output reg  [2:0]             m31_current_state // Current cache state
    , output reg                    m31_state_valid   // State lookup valid
    // Global cache state monitoring outputs
    , output reg  [31:0]            cache_hits         // Total cache hits
    , output reg  [31:0]            cache_misses       // Total cache misses
    , output reg  [31:0]            state_transitions  // Total state transitions
    , output reg  [NUM_MASTER-1:0] coherency_conflict // Coherency conflicts per master
);

    // MOESI Cache State Encodings
    localparam [2:0] STATE_INVALID   = 3'b000;  // I - Invalid (not cached)
    localparam [2:0] STATE_SHARED    = 3'b001;  // S - Shared (read-only, may be in other caches)
    localparam [2:0] STATE_EXCLUSIVE = 3'b010;  // E - Exclusive (read-only, only copy)
    localparam [2:0] STATE_OWNED     = 3'b011;  // O - Owned (dirty, shared with others)
    localparam [2:0] STATE_MODIFIED  = 3'b100;  // M - Modified (dirty, only copy)
    localparam [2:0] STATE_RESERVED1 = 3'b101;  // Reserved for future use
    localparam [2:0] STATE_RESERVED2 = 3'b110;  // Reserved for future use
    localparam [2:0] STATE_ERROR     = 3'b111;  // Error state

    // Cache Line State Tracking
    // Each cache line tracks: address tag, state per master, LRU info
    reg [WIDTH_AD-7:0] cache_tag [CACHE_LINE_ENTRIES-1:0];     // Address tag (excluding lower 6 bits)
    reg [2:0]          cache_state [CACHE_LINE_ENTRIES-1:0][NUM_MASTER-1:0]; // State per master
    reg                cache_valid [CACHE_LINE_ENTRIES-1:0];   // Valid cache line
    reg [7:0]          cache_lru [CACHE_LINE_ENTRIES-1:0];     // LRU counter (0=most recent)
    reg [NUM_MASTER-1:0] cache_owner [CACHE_LINE_ENTRIES-1:0]; // Master that owns this line

    // Internal Cache Management Signals
    reg [9:0] cache_index [NUM_MASTER-1:0];     // Cache index for each master
    reg       cache_hit [NUM_MASTER-1:0];       // Cache hit indicator
    reg [9:0] victim_index;                     // Index for cache replacement
    reg       replacement_needed;               // Need to replace cache line
    
    // Cache Lookup Logic
    // Determines cache index and hit/miss for each master
    integer k;
    always @(*) begin
        // Master 0 cache lookup
        cache_index[0] = m0_addr[15:6];  // Use middle bits for index
        cache_hit[0] = 1'b0;
        m0_current_state = STATE_INVALID;
        m0_state_valid = 1'b0;
        
        if (m0_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m0_addr[WIDTH_AD-1:6])) begin
                    cache_hit[0] = 1'b1;
                    cache_index[0] = k[9:0];
                    m0_current_state = cache_state[k][0];
                    m0_state_valid = 1'b1;
                end
            end
        end
        
        // Master 1 cache lookup
        cache_index[1] = m1_addr[15:6];  // Use middle bits for index
        cache_hit[1] = 1'b0;
        m1_current_state = STATE_INVALID;
        m1_state_valid = 1'b0;
        
        if (m1_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m1_addr[WIDTH_AD-1:6])) begin
                    cache_hit[1] = 1'b1;
                    cache_index[1] = k[9:0];
                    m1_current_state = cache_state[k][1];
                    m1_state_valid = 1'b1;
                end
            end
        end
        
        // Master 2 cache lookup
        cache_index[2] = m2_addr[15:6];  // Use middle bits for index
        cache_hit[2] = 1'b0;
        m2_current_state = STATE_INVALID;
        m2_state_valid = 1'b0;
        
        if (m2_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m2_addr[WIDTH_AD-1:6])) begin
                    cache_hit[2] = 1'b1;
                    cache_index[2] = k[9:0];
                    m2_current_state = cache_state[k][2];
                    m2_state_valid = 1'b1;
                end
            end
        end
        
        // Master 3 cache lookup
        cache_index[3] = m3_addr[15:6];  // Use middle bits for index
        cache_hit[3] = 1'b0;
        m3_current_state = STATE_INVALID;
        m3_state_valid = 1'b0;
        
        if (m3_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m3_addr[WIDTH_AD-1:6])) begin
                    cache_hit[3] = 1'b1;
                    cache_index[3] = k[9:0];
                    m3_current_state = cache_state[k][3];
                    m3_state_valid = 1'b1;
                end
            end
        end
        
        // Master 4 cache lookup
        cache_index[4] = m4_addr[15:6];  // Use middle bits for index
        cache_hit[4] = 1'b0;
        m4_current_state = STATE_INVALID;
        m4_state_valid = 1'b0;
        
        if (m4_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m4_addr[WIDTH_AD-1:6])) begin
                    cache_hit[4] = 1'b1;
                    cache_index[4] = k[9:0];
                    m4_current_state = cache_state[k][4];
                    m4_state_valid = 1'b1;
                end
            end
        end
        
        // Master 5 cache lookup
        cache_index[5] = m5_addr[15:6];  // Use middle bits for index
        cache_hit[5] = 1'b0;
        m5_current_state = STATE_INVALID;
