                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 29) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[29] <= 1'b0;
            
            // Master 30 state update processing
            if (m30_state_update) begin
                if (cache_hit[30]) begin
                    // Update existing cache line
                    cache_state[cache_index[30]][30] <= m30_new_state;
                    cache_lru[cache_index[30]] <= 8'h00;  // Mark as most recent
                    cache_hits <= cache_hits + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Check for coherency conflicts
                    if (m30_new_state == STATE_MODIFIED || m30_new_state == STATE_EXCLUSIVE) begin
                        for (k = 0; k < NUM_MASTER; k = k + 1) begin
                            if (k != 30 && cache_state[cache_index[30]][k] != STATE_INVALID) begin
                                coherency_conflict[30] <= 1'b1;
                                // Invalidate other masters' copies
                                cache_state[cache_index[30]][k] <= STATE_INVALID;
                            end
                        end
                    end
                    
                end else begin
                    // Allocate new cache line
                    cache_valid[victim_index] <= 1'b1;
                    cache_tag[victim_index] <= m30_addr[WIDTH_AD-1:6];
                    cache_state[victim_index][30] <= m30_new_state;
                    cache_lru[victim_index] <= 8'h00;
                    cache_owner[victim_index][30] <= 1'b1;
                    cache_misses <= cache_misses + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 30) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[30] <= 1'b0;
            
            // Master 31 state update processing
            if (m31_state_update) begin
                if (cache_hit[31]) begin
                    // Update existing cache line
                    cache_state[cache_index[31]][31] <= m31_new_state;
                    cache_lru[cache_index[31]] <= 8'h00;  // Mark as most recent
                    cache_hits <= cache_hits + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Check for coherency conflicts
                    if (m31_new_state == STATE_MODIFIED || m31_new_state == STATE_EXCLUSIVE) begin
                        for (k = 0; k < NUM_MASTER; k = k + 1) begin
                            if (k != 31 && cache_state[cache_index[31]][k] != STATE_INVALID) begin
                                coherency_conflict[31] <= 1'b1;
                                // Invalidate other masters' copies
                                cache_state[cache_index[31]][k] <= STATE_INVALID;
                            end
                        end
                    end
                    
                end else begin
                    // Allocate new cache line
                    cache_valid[victim_index] <= 1'b1;
                    cache_tag[victim_index] <= m31_addr[WIDTH_AD-1:6];
                    cache_state[victim_index][31] <= m31_new_state;
                    cache_lru[victim_index] <= 8'h00;
                    cache_owner[victim_index][31] <= 1'b1;
                    cache_misses <= cache_misses + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 31) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[31] <= 1'b0;
            
        end
    end

    // MOESI Protocol State Transition Validation
    // Ensures only valid MOESI transitions occur
    function automatic logic valid_transition;
        input [2:0] current_state;
        input [2:0] new_state;
        begin
            case (current_state)
                STATE_INVALID: begin
                    // From Invalid: can go to any state except Owned
                    valid_transition = (new_state != STATE_OWNED);
                end
                STATE_SHARED: begin
                    // From Shared: can go to Invalid, Exclusive, or Modified
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_EXCLUSIVE) || 
                                     (new_state == STATE_MODIFIED);
                end
                STATE_EXCLUSIVE: begin
                    // From Exclusive: can go to Invalid, Shared, or Modified
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_SHARED) || 
                                     (new_state == STATE_MODIFIED);
                end
                STATE_OWNED: begin
                    // From Owned: can go to Invalid or Modified
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_MODIFIED);
                end
                STATE_MODIFIED: begin
                    // From Modified: can go to Invalid, Shared, or Owned
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_SHARED) || 
                                     (new_state == STATE_OWNED);
                end
                default: begin
                    valid_transition = 1'b0;  // Invalid current state
                end
            endcase
        end
    endfunction

endmodule


