    // Master 30 exclusive access interface
    , input  wire [WIDTH_ID-1:0]       m30_awid
    , input  wire [WIDTH_AD-1:0]       m30_awaddr
    , input  wire [2:0]                m30_awsize
    , input  wire                      m30_awlock
    , input  wire                      m30_awvalid
    , input  wire                      m30_awready
    , input  wire [WIDTH_ID-1:0]       m30_arid
    , input  wire [WIDTH_AD-1:0]       m30_araddr
    , input  wire [2:0]                m30_arsize
    , input  wire                      m30_arlock
    , input  wire                      m30_arvalid
