                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m27_awaddr, m27_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
                if (m28_awvalid && m28_awready && !m28_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m28_awaddr, m28_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
                if (m29_awvalid && m29_awready && !m29_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m29_awaddr, m29_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
                if (m30_awvalid && m30_awready && !m30_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m30_awaddr, m30_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
                if (m31_awvalid && m31_awready && !m31_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m31_awaddr, m31_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
            end
        end
    end

    // Output assignments
    assign exclusive_count = exclusive_count_reg;

endmodule

