    , input  wire [15:0]            m31_dvm_asid       // Address Space ID
    , input  wire                   m31_dvm_valid      // DVM request valid
    , output reg                    m31_dvm_ready      // DVM request ready
    , output reg                    m31_dvm_complete   // DVM operation complete
