                    m29_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[29]) begin
                // Clear completion flag
                tlb_op_complete[29] <= 1'b0;
                m29_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[29] <= 1'b0;
            end
            
            // Update valid entry count for master 29
            tlb_entries_per_master[29] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[29][k]) begin
                    tlb_entries_per_master[29] <= tlb_entries_per_master[29] + 1;
                end
            end
            
            // Master 30 TLB operation processing
            if (m30_tlb_valid && m30_tlb_ready) begin
                // Start TLB operation
                tlb_op_pending[30] <= 1'b1;
                m30_tlb_ready <= 1'b0;
                invalidation_counter[30] <= 32'h00000000;
                tlb_invalidation_active <= 1'b1;
                
                case (m30_tlb_op)
                    TLB_INV_ALL: begin
                        // Invalidate all TLB entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[30][k]) begin
                                tlb_valid[30][k] <= 1'b0;
                                invalidation_counter[30] <= invalidation_counter[30] + 1;
                            end
                        end
                        tlb_entries_per_master[30] <= 32'h00000000;
                    end
                    
                    TLB_INV_ASID: begin
                        // Invalidate entries matching ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[30][k] && (tlb_asid[30][k] == m30_tlb_asid) && !tlb_global[30][k]) begin
                                tlb_valid[30][k] <= 1'b0;
                                invalidation_counter[30] <= invalidation_counter[30] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA: begin
                        // Invalidate entries matching Virtual Address
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[30][k] && (tlb_tag[30][k] == m30_tlb_va[WIDTH_AD-1:12])) begin
                                tlb_valid[30][k] <= 1'b0;
                                invalidation_counter[30] <= invalidation_counter[30] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA_ASID: begin
                        // Invalidate entries matching both VA and ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[30][k] && 
                                (tlb_tag[30][k] == m30_tlb_va[WIDTH_AD-1:12]) &&
                                (tlb_asid[30][k] == m30_tlb_asid) && !tlb_global[30][k]) begin
                                tlb_valid[30][k] <= 1'b0;
                                invalidation_counter[30] <= invalidation_counter[30] + 1;
                            end
                        end
                    end
                    
                    TLB_FLUSH: begin
                        // Flush all entries including global ones
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[30][k]) begin
                                tlb_valid[30][k] <= 1'b0;
                                tlb_global[30][k] <= 1'b0;
                                invalidation_counter[30] <= invalidation_counter[30] + 1;
                            end
                        end
                        tlb_entries_per_master[30] <= 32'h00000000;
                    end
                    
                    TLB_LOOKUP: begin
                        // TLB lookup operation (read-only)
                        // Count matching entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[30][k] && 
                                (tlb_tag[30][k] == m30_tlb_va[WIDTH_AD-1:12]) &&
                                ((tlb_asid[30][k] == m30_tlb_asid) || tlb_global[30][k])) begin
                                invalidation_counter[30] <= invalidation_counter[30] + 1;
                            end
                        end
                    end
                    
                    TLB_SYNC: begin
                        // TLB synchronization - no actual operation
                        invalidation_counter[30] <= 32'h00000001;
                    end
                    
                    default: begin
                        // Unknown operation
                        tlb_maintenance_error[30] <= 1'b1;
                        invalidation_counter[30] <= 32'h00000000;
                    end
                endcase
                
            end else if (tlb_op_pending[30] && !tlb_op_complete[30]) begin
                // Complete the TLB operation
                tlb_op_complete[30] <= 1'b1;
                tlb_op_pending[30] <= 1'b0;
                m30_tlb_ready <= 1'b1;
                m30_tlb_complete <= 1'b1;
                m30_tlb_entries_inv <= invalidation_counter[30];
                
                // Update statistics
                tlb_total_invalidations <= tlb_total_invalidations + invalidation_counter[30];
                
                // Set response based on operation result
                if (tlb_maintenance_error[30]) begin
                    m30_tlb_resp <= TLB_RESP_ERROR;
                end else if (invalidation_counter[30] == 0 && m30_tlb_op != TLB_SYNC) begin
                    m30_tlb_resp <= TLB_RESP_PARTIAL;
                end else begin
                    m30_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[30]) begin
                // Clear completion flag
                tlb_op_complete[30] <= 1'b0;
                m30_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[30] <= 1'b0;
            end
            
            // Update valid entry count for master 30
            tlb_entries_per_master[30] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[30][k]) begin
                    tlb_entries_per_master[30] <= tlb_entries_per_master[30] + 1;
                end
            end
            
            // Master 31 TLB operation processing
            if (m31_tlb_valid && m31_tlb_ready) begin
                // Start TLB operation
                tlb_op_pending[31] <= 1'b1;
                m31_tlb_ready <= 1'b0;
                invalidation_counter[31] <= 32'h00000000;
                tlb_invalidation_active <= 1'b1;
                
                case (m31_tlb_op)
                    TLB_INV_ALL: begin
                        // Invalidate all TLB entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[31][k]) begin
                                tlb_valid[31][k] <= 1'b0;
                                invalidation_counter[31] <= invalidation_counter[31] + 1;
                            end
                        end
                        tlb_entries_per_master[31] <= 32'h00000000;
                    end
                    
                    TLB_INV_ASID: begin
                        // Invalidate entries matching ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[31][k] && (tlb_asid[31][k] == m31_tlb_asid) && !tlb_global[31][k]) begin
                                tlb_valid[31][k] <= 1'b0;
                                invalidation_counter[31] <= invalidation_counter[31] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA: begin
                        // Invalidate entries matching Virtual Address
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[31][k] && (tlb_tag[31][k] == m31_tlb_va[WIDTH_AD-1:12])) begin
                                tlb_valid[31][k] <= 1'b0;
                                invalidation_counter[31] <= invalidation_counter[31] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA_ASID: begin
                        // Invalidate entries matching both VA and ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[31][k] && 
                                (tlb_tag[31][k] == m31_tlb_va[WIDTH_AD-1:12]) &&
                                (tlb_asid[31][k] == m31_tlb_asid) && !tlb_global[31][k]) begin
                                tlb_valid[31][k] <= 1'b0;
                                invalidation_counter[31] <= invalidation_counter[31] + 1;
                            end
                        end
                    end
                    
                    TLB_FLUSH: begin
                        // Flush all entries including global ones
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[31][k]) begin
                                tlb_valid[31][k] <= 1'b0;
                                tlb_global[31][k] <= 1'b0;
                                invalidation_counter[31] <= invalidation_counter[31] + 1;
                            end
                        end
                        tlb_entries_per_master[31] <= 32'h00000000;
                    end
                    
                    TLB_LOOKUP: begin
                        // TLB lookup operation (read-only)
                        // Count matching entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[31][k] && 
                                (tlb_tag[31][k] == m31_tlb_va[WIDTH_AD-1:12]) &&
                                ((tlb_asid[31][k] == m31_tlb_asid) || tlb_global[31][k])) begin
                                invalidation_counter[31] <= invalidation_counter[31] + 1;
                            end
                        end
                    end
                    
                    TLB_SYNC: begin
                        // TLB synchronization - no actual operation
                        invalidation_counter[31] <= 32'h00000001;
                    end
                    
                    default: begin
                        // Unknown operation
                        tlb_maintenance_error[31] <= 1'b1;
                        invalidation_counter[31] <= 32'h00000000;
                    end
                endcase
                
            end else if (tlb_op_pending[31] && !tlb_op_complete[31]) begin
                // Complete the TLB operation
                tlb_op_complete[31] <= 1'b1;
                tlb_op_pending[31] <= 1'b0;
                m31_tlb_ready <= 1'b1;
                m31_tlb_complete <= 1'b1;
                m31_tlb_entries_inv <= invalidation_counter[31];
                
                // Update statistics
                tlb_total_invalidations <= tlb_total_invalidations + invalidation_counter[31];
                
                // Set response based on operation result
                if (tlb_maintenance_error[31]) begin
                    m31_tlb_resp <= TLB_RESP_ERROR;
                end else if (invalidation_counter[31] == 0 && m31_tlb_op != TLB_SYNC) begin
                    m31_tlb_resp <= TLB_RESP_PARTIAL;
                end else begin
                    m31_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[31]) begin
                // Clear completion flag
                tlb_op_complete[31] <= 1'b0;
                m31_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[31] <= 1'b0;
            end
            
            // Update valid entry count for master 31
            tlb_entries_per_master[31] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[31][k]) begin
                    tlb_entries_per_master[31] <= tlb_entries_per_master[31] + 1;
                end
            end
            
            // Update global TLB invalidation status
            tlb_invalidation_active <= |tlb_op_pending;
            
        end
    end

    // TLB Age Management for LRU Replacement
    // Ages all TLB entries periodically to support replacement
    reg [15:0] age_counter;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            age_counter <= 16'h0000;
        end else begin
            age_counter <= age_counter + 1;
            
            // Age TLB entries every 256 cycles
            if (age_counter[7:0] == 8'h00) begin
                // Age master 0 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[0][k] && tlb_age[0][k] < 8'hFF) begin
                        tlb_age[0][k] <= tlb_age[0][k] + 1;
                    end
                end
                // Age master 1 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
