                        tlb_age[5][k] <= tlb_age[5][k] + 1;
                    end
                end
                // Age master 6 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[6][k] && tlb_age[6][k] < 8'hFF) begin
                        tlb_age[6][k] <= tlb_age[6][k] + 1;
                    end
