                // Age master 7 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[7][k] && tlb_age[7][k] < 8'hFF) begin
                        tlb_age[7][k] <= tlb_age[7][k] + 1;
                    end
