                // Age master 8 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[8][k] && tlb_age[8][k] < 8'hFF) begin
                        tlb_age[8][k] <= tlb_age[8][k] + 1;
                    end
                end
                // Age master 9 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[9][k] && tlb_age[9][k] < 8'hFF) begin
                        tlb_age[9][k] <= tlb_age[9][k] + 1;
                    end
                end
                // Age master 10 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[10][k] && tlb_age[10][k] < 8'hFF) begin
                        tlb_age[10][k] <= tlb_age[10][k] + 1;
                    end
                end
                // Age master 11 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[11][k] && tlb_age[11][k] < 8'hFF) begin
                        tlb_age[11][k] <= tlb_age[11][k] + 1;
                    end
                end
                // Age master 12 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
