                        tlb_age[12][k] <= tlb_age[12][k] + 1;
                    end
                end
                // Age master 13 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[13][k] && tlb_age[13][k] < 8'hFF) begin
                        tlb_age[13][k] <= tlb_age[13][k] + 1;
