            end
            
            // Master 25 dependency tracking
            if (m25_txn_active) begin
                transaction_outstanding[25] <= 1'b1;
                if (dependency_age[25] < 16'hFFFF) begin
                    dependency_age[25] <= dependency_age[25] + 1;
                end
                
                // Detect potential deadlock
                if (dependency_age[25] > 16'hFF00) begin
                    deadlock_candidates[25] <= 1'b1;
                end
            end else begin
                transaction_outstanding[25] <= 1'b0;
                dependency_age[25] <= 16'h0000;
                deadlock_candidates[25] <= 1'b0;
            end
            
            // Update coherency conflicts
            if (m25_coherency_req != 2'b00 && !m25_coherency_grant) begin
                coherency_conflicts[25] <= 1'b1;
            end else begin
                coherency_conflicts[25] <= 1'b0;
